export function directoryCollectionStatus(entry:CompetitionDirectoryEntry):'pending'|'entry_only' {
 const url=new URL(entry.entryUrl);
 return entry.entryType==='高校通知'||/\.(?:pdf|docx?|xlsx?)(?:$|[?#])/i.test(entry.entryUrl)||url.hostname==='mp.weixin.qq.com'||/\/(?:info|details|show)[\/_-]|\/\d{4}\/\d{2}\//.test(url.pathname)?'entry_only':'pending';
}
